using namespace std;

const int MAXN = 200005;
const int LOG = 18;

vector<pair<int,int>> adj[MAXN];
int par[MAXN][LOG], depth[MAXN];
long long maxEdge[MAXN][LOG];

void dfs(int u, int p, int d) {
    par[u][0] = p;
    depth[u] = d;
    for (auto [v, w] : adj[u]) {
        if (v != p) {
            maxEdge[v][0] = w;
            dfs(v, u, d+1);
        }
    }
}

long long query(int u, int v) {
    long long res = 0;
    if (depth[u] < depth[v]) swap(u, v);
    int diff = depth[u] - depth[v];
    for (int i = 0; i < LOG; i++) {
        if ((diff >> i) & 1) {
            res = max(res, maxEdge[u][i]);
            u = par[u][i];
        }
    }
    if (u == v) return res;
    for (int i = LOG-1; i >= 0; i--) {
        if (par[u][i] != par[v][i]) {
            res = max(res, max(maxEdge[u][i], maxEdge[v][i]));
            u = par[u][i];
            v = par[v][i];
        }
    }
    res = max(res, max(maxEdge[u][0], maxEdge[v][0]));
    return res;
}

