#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);

struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n + 1);
        sz.assign(n + 1, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    struct Edge {
        int u, v;
        ll w;
    };
    vector<Edge> edges(M);
    ll totalMST = 0;

    for (int i = 0; i < M; ++i) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
    }

    // Build MST by Kruskal
    vector<int> ord(M);
    iota(ord.begin(), ord.end(), 0);
    sort(ord.begin(), ord.end(), [&](int i, int j) {
        return edges[i].w < edges[j].w;
    });

    vector<vector<pair<int,ll>>> g(N + 1);
    DSU dsu(N);
    for (int id : ord) {
        auto &e = edges[id];
        if (dsu.unite(e.u, e.v)) {
            totalMST += e.w;
            g[e.u].push_back({e.v, e.w});
            g[e.v].push_back({e.u, e.w});
        }
    }

    // The answer for (S,T) is:
    // total weight of MST - maximum edge weight on path S-T in MST
    // because removing one edge on that path splits the tree into two components,
    // one containing S and the other containing T, and to minimize remaining sum
    // we remove the heaviest such edge.

    int LOG = 1;
    while ((1 << LOG) <= N) ++LOG;

    vector<int> depth(N + 1, 0);
    vector<vector<int>> up(LOG, vector<int>(N + 1, 0));
    vector<vector<ll>> mx(LOG, vector<ll>(N + 1, 0));

    // DFS/BFS from 1
    vector<int> parent(N + 1, 0);
    vector<ll> pw(N + 1, 0);
    queue<int> q;
    q.push(1);
    parent[1] = 0;
    depth[1] = 0;

    vector<int> vis(N + 1, 0);
    vis[1] = 1;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto [to, w] : g[v]) {
            if (vis[to]) continue;
            vis[to] = 1;
            parent[to] = v;
            pw[to] = w;
            depth[to] = depth[v] + 1;
            q.push(to);
        }
    }

    for (int v = 1; v <= N; ++v) {
        up[0][v] = parent[v];
        mx[0][v] = pw[v];
    }

    for (int k = 1; k < LOG; ++k) {
        for (int v = 1; v <= N; ++v) {
            up[k][v] = up[k - 1][ up[k - 1][v] ];
            mx[k][v] = max(mx[k - 1][v], mx[k - 1][ up[k - 1][v] ]);
        }
    }

    auto max_on_path = [&](int a, int b) -> ll {
        ll res = 0;
        if (depth[a] < depth[b]) swap(a, b);

        int diff = depth[a] - depth[b];
        for (int k = LOG - 1; k >= 0; --k) {
            if (diff & (1 << k)) {
                res = max(res, mx[k][a]);
                a = up[k][a];
            }
        }

        if (a == b) return res;

        for (int k = LOG - 1; k >= 0; --k) {
            if (up[k][a] != up[k][b]) {
                res = max(res, mx[k][a]);
                res = max(res, mx[k][b]);
                a = up[k][a];
                b = up[k][b];
            }
        }

        res = max(res, mx[0][a]);
        res = max(res, mx[0][b]);
        return res;
    };

    int Q;
    cin >> Q;
    while (Q--) {
        int S, T;
        cin >> S >> T;
        ll ans = totalMST - max_on_path(S, T);
        cout << ans << '\n';
    }

    return 0;
}

