#define MAXN 200005
#define LOGN 18

typedef struct {
    int u, v, w;
} Edge;

typedef struct {
    int to, w;
} Adj;

Edge edges[MAXN];
int parent[MAXN];
Adj adj[MAXN * 2];
int head[MAXN], nxt[MAXN * 2], to[MAXN * 2], wgt[MAXN * 2];
int edge_cnt;

int depth[MAXN];
int up[LOGN][MAXN];
int max_up[LOGN][MAXN];
int total_weight;

int cmp(const void *a, const void *b) {
    return ((Edge*)a)->w - ((Edge*)b)->w;
}

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void union_set(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra != rb) parent[ra] = rb;
}

void add_edge(int u, int v, int w) {
    to[edge_cnt] = v;
    wgt[edge_cnt] = w;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

void dfs(int u, int p, int w) {
    depth[u] = depth[p] + 1;
    up[0][u] = p;
    max_up[0][u] = w;
    for (int i = 1; i < LOGN; ++i) {
        up[i][u] = up[i-1][up[i-1][u]];
        int tmp = max_up[i-1][u];
        int tmp2 = max_up[i-1][up[i-1][u]];
        max_up[i][u] = tmp > tmp2 ? tmp : tmp2;
    }
    for (int e = head[u]; e != -1; e = nxt[e]) {
        int v = to[e];
        if (v == p) continue;
        dfs(v, u, wgt[e]);
    }
}

int get_max_on_path(int u, int v) {
    int ans = 0;
    if (depth[u] < depth[v]) { int t = u; u = v; v = t; }
    int diff = depth[u] - depth[v];
    for (int i = 0; i < LOGN; ++i) {
        if (diff & (1 << i)) {
            if (max_up[i][u] > ans) ans = max_up[i][u];
            u = up[i][u];
        }
    }
    if (u == v) return ans;
    for (int i = LOGN - 1; i >= 0; --i) {
        if (up[i][u] != up[i][v]) {
            if (max_up[i][u] > ans) ans = max_up[i][u];
            if (max_up[i][v] > ans) ans = max_up[i][v];
            u = up[i][u];
            v = up[i][v];
        }
    }
    if (max_up[0][u] > ans) ans = max_up[0][u];
    if (max_up[0][v] > ans) ans = max_up[0][v];
    return ans;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    for (int i = 0; i < M; ++i) {
        scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].w);
    }
    qsort(edges, M, sizeof(Edge), cmp);
    for (int i = 1; i <= N; ++i) parent[i] = i;
    memset(head, -1, sizeof(head));
    edge_cnt = 0;
    total_weight = 0;
    for (int i = 0; i < M; ++i) {
        int u = edges[i].u, v = edges[i].v, w = edges[i].w;
        if (find(u) != find(v)) {
            union_set(u, v);
            total_weight += w;
            add_edge(u, v, w);
            add_edge(v, u, w);
        }
    }
    depth[0] = -1;
    dfs(1, 0, 0);
    int Q;
    scanf("%d", &Q);
    while (Q--) {
        int s, t;
        scanf("%d %d", &s, &t);
        int max_edge = get_max_on_path(s, t);
        printf("%d\n", total_weight - max_edge);
    }
    return 0;
}

