#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int u, v;
    ll w;
} Edge;

typedef struct {
    int to, next;
    ll w;
} AdjEdge;

static int cmp_edge(const void *a, const void *b) {
    ll x = ((const Edge*)a)->w;
    ll y = ((const Edge*)b)->w;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int *uf_par, *uf_sz;

int uf_find(int x) {
    while (uf_par[x] != x) {
        uf_par[x] = uf_par[uf_par[x]];
        x = uf_par[x];
    }
    return x;
}

int uf_unite(int a, int b) {
    a = uf_find(a);
    b = uf_find(b);
    if (a == b) return 0;
    if (uf_sz[a] < uf_sz[b]) {
        int t = a; a = b; b = t;
    }
    uf_par[b] = a;
    uf_sz[a] += uf_sz[b];
    return 1;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    Edge *edges = (Edge*)malloc(sizeof(Edge) * M);
    for (int i = 0; i < M; i++) {
        scanf("%d %d %lld", &edges[i].u, &edges[i].v, &edges[i].w);
        edges[i].u--;
        edges[i].v--;
    }

    qsort(edges, M, sizeof(Edge), cmp_edge);

    uf_par = (int*)malloc(sizeof(int) * N);
    uf_sz  = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) {
        uf_par[i] = i;
        uf_sz[i] = 1;
    }

    int treeEdges = N - 1;
    AdjEdge *adj = (AdjEdge*)malloc(sizeof(AdjEdge) * (2 * treeEdges));
    int *head = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) head[i] = -1;

    ll mst_total = 0;
    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        if (uf_unite(edges[i].u, edges[i].v)) {
            mst_total += edges[i].w;

            adj[ecnt].to = edges[i].v;
            adj[ecnt].w = edges[i].w;
            adj[ecnt].next = head[edges[i].u];
            head[edges[i].u] = ecnt++;

            adj[ecnt].to = edges[i].u;
            adj[ecnt].w = edges[i].w;
            adj[ecnt].next = head[edges[i].v];
            head[edges[i].v] = ecnt++;
        }
    }

    int LOG = 1;
    while ((1 << LOG) <= N) LOG++;

    int *depth = (int*)malloc(sizeof(int) * N);
    int **up = (int**)malloc(sizeof(int*) * LOG);
    ll **mx = (ll**)malloc(sizeof(ll*) * LOG);
    for (int k = 0; k < LOG; k++) {
        up[k] = (int*)malloc(sizeof(int) * N);
        mx[k] = (ll*)malloc(sizeof(ll) * N);
    }

    int *queue = (int*)malloc(sizeof(int) * N);
    int front = 0, back = 0;
    queue[back++] = 0;
    depth[0] = 0;
    up[0][0] = -1;
    mx[0][0] = 0;

    int *vis = (int*)calloc(N, sizeof(int));
    vis[0] = 1;

    while (front < back) {
        int v = queue[front++];
        for (int e = head[v]; e != -1; e = adj[e].next) {
            int to = adj[e].to;
            if (vis[to]) continue;
            vis[to] = 1;
            depth[to] = depth[v] + 1;
            up[0][to] = v;
            mx[0][to] = adj[e].w;
            queue[back++] = to;
        }
    }
    free(vis);
    free(queue);

    for (int k = 1; k < LOG; k++) {
        for (int v = 0; v < N; v++) {
            int p = up[k-1][v];
            if (p == -1) {
                up[k][v] = -1;
                mx[k][v] = mx[k-1][v];
            } else {
                up[k][v] = up[k-1][p];
                mx[k][v] = mx[k-1][v] > mx[k-1][p] ? mx[k-1][v] : mx[k-1][p];
            }
        }
    }

    int Q;
    scanf("%d", &Q);

    while (Q--) {
        int s, t;
        scanf("%d %d", &s, &t);
        s--; t--;

        ll ans_remove = 0;
        int a = s, b = t;

        if (depth[a] < depth[b]) {
            int tmp = a; a = b; b = tmp;
        }

        ll best = 0;

        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; k++) {
            if ((diff >> k) & 1) {
                if (mx[k][a] > best) best = mx[k][a];
                a = up[k][a];
            }
        }

        if (a != b) {
            for (int k = LOG - 1; k >= 0; k--) {
                if (up[k][a] != up[k][b]) {
                    if (mx[k][a] > best) best = mx[k][a];
                    if (mx[k][b] > best) best = mx[k][b];
                    a = up[k][a];
                    b = up[k][b];
                }
            }
            if (mx[0][a] > best) best = mx[0][a];
            if (mx[0][b] > best) best = mx[0][b];
        }

        ans_remove = best;
        printf("%lld\n", mst_total - ans_remove);
    }

    free(edges);
    free(uf_par);
    free(uf_sz);
    free(adj);
    free(head);
    free(depth);
    for (int k = 0; k < LOG; k++) {
        free(up[k]);
        free(mx[k]);
    }
    free(up);
    free(mx);

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static class Edge implements Comparable<Edge> {
        int u, v, w;
        Edge(int u, int v, int w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
        public int compareTo(Edge o) {
            return Integer.compare(this.w, o.w);
        }
    }

    static class DSU {
        int[] parent, rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        boolean union(int x, int y) {
            int rx = find(x), ry = find(y);
            if (rx == ry) return false;
            if (rank[rx] < rank[ry]) parent[rx] = ry;
            else if (rank[rx] > rank[ry]) parent[ry] = rx;
            else { parent[ry] = rx; rank[rx]++; }
            return true;
        }
    }

    static List<int[]>[] tree;
    static int[][] up;
    static int[][] maxEdge;
    static int[] depth;
    static int LOG;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        Edge[] edges = new Edge[M];
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            int w = Integer.parseInt(st.nextToken());
            edges[i] = new Edge(u, v, w);
        }

        Arrays.sort(edges);
        DSU dsu = new DSU(N);
        tree = new ArrayList[N];
        for (int i = 0; i < N; i++) tree[i] = new ArrayList<>();

        long mstWeight = 0;
        for (Edge e : edges) {
            if (dsu.union(e.u, e.v)) {
                mstWeight += e.w;
                tree[e.u].add(new int[]{e.v, e.w});
                tree[e.v].add(new int[]{e.u, e.w});
            }
        }

        LOG = (int)(Math.log(N)/Math.log(2)) + 1;
        up = new int[N][LOG];
        maxEdge = new int[N][LOG];
        depth = new int[N];

        dfs(0, -1, 0, 0);

        int Q = Integer.parseInt(br.readLine());
        StringBuilder sb = new StringBuilder();
        while (Q-- > 0) {
            st = new StringTokenizer(br.readLine());
            int s = Integer.parseInt(st.nextToken()) - 1;
            int t = Integer.parseInt(st.nextToken()) - 1;
            int maxOnPath = query(s, t);
            sb.append(mstWeight - maxOnPath).append("\n");
        }
        System.out.print(sb);
    }

    static void dfs(int u, int p, int w, int d) {
        depth[u] = d;
        up[u][0] = p == -1 ? u : p;
        maxEdge[u][0] = w;
        for (int i = 1; i < LOG; i++) {
            up[u][i] = up[up[u][i-1]][i-1];
            maxEdge[u][i] = Math.max(maxEdge[u][i-1], maxEdge[up[u][i-1]][i-1]);
        }
        for (int[] edge : tree[u]) {
            int v = edge[0], weight = edge[1];
            if (v == p) continue;
            dfs(v, u, weight, d + 1);
        }
    }

    static int query(int u, int v) {
        if (depth[u] < depth[v]) { int t = u; u = v; v = t; }
        int maxVal = 0;
        int diff = depth[u] - depth[v];
        for (int i = 0; i < LOG; i++) {
            if ((diff & (1 << i)) != 0) {
                maxVal = Math.max(maxVal, maxEdge[u][i]);
                u = up[u][i];
            }
        }
        if (u == v) return maxVal;
        for (int i = LOG - 1; i >= 0; i--) {
            if (up[u][i] != up[v][i]) {
                maxVal = Math.max(maxVal, Math.max(maxEdge[u][i], maxEdge[v][i]));
                u = up[u][i];
                v = up[v][i];
            }
        }
        maxVal = Math.max(maxVal, Math.max(maxEdge[u][0], maxEdge[v][0]));
        return maxVal;
    }
}

