public class Main {
    static int[] parent, depth;
    static long[] maxEdge;
    static int[][] up;
    static long[][] upMax;
    static List<long[]>[] adj;
    static int LOG = 18;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        long[][] edges = new long[M][3];
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            edges[i][0] = Long.parseLong(st.nextToken());
            edges[i][1] = Long.parseLong(st.nextToken());
            edges[i][2] = Long.parseLong(st.nextToken());
        }
        Arrays.sort(edges, (x, y) -> Long.compare(x[2], y[2]));

        // Kruskal's MST
        int[] dsu = new int[N + 1];
        for (int i = 0; i <= N; i++) dsu[i] = i;
        adj = new List[N + 1];
        for (int i = 0; i <= N; i++) adj[i] = new ArrayList<>();
        long mstWeight = 0;
        for (long[] e : edges) {
            int u = (int)e[0], v = (int)e[1]; long w = e[2];
            if (find(dsu, u) != find(dsu, v)) {
                union(dsu, u, v);
                adj[u].add(new long[]{v, w});
                adj[v].add(new long[]{u, w});
                mstWeight += w;
            }
        }

        depth = new int[N + 1];
        up = new int[N + 1][LOG];
        upMax = new long[N + 1][LOG];
        bfs(1, N);

        int Q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Q; i++) {
            st = new StringTokenizer(br.readLine());
            int s = Integer.parseInt(st.nextToken()), t = Integer.parseInt(st.nextToken());
            sb.append(mstWeight - maxOnPath(s, t)).append('\n');
        }
        System.out.print(sb);
    }

    static void bfs(int root, int N) {
        Queue<Integer> q = new LinkedList<>();
        boolean[] vis = new boolean[N + 1];
        q.add(root); vis[root] = true; depth[root] = 0; up[root][0] = root; upMax[root][0] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int k = 1; k < LOG; k++) { up[u][k] = up[up[u][k-1]][k-1]; upMax[u][k] = Math.max(upMax[u][k-1], upMax[up[u][k-1]][k-1]); }
            for (long[] e : adj[u]) { int v = (int)e[0]; long w = e[1]; if (!vis[v]) { vis[v]=true; depth[v]=depth[u]+1; up[v][0]=u; upMax[v][0]=w; q.add(v); } }
        }
    }

    static long maxOnPath(int u, int v) {
        long res = 0;
        if (depth[u] < depth[v]) { int tmp=u; u=v; v=tmp; }
        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++) if (((diff>>k)&1)==1) { res=Math.max(res,upMax[u][k]); u=up[u][k]; }
        if (u==v) return res;
        for (int k=LOG-1;k>=0;k--) if (up[u][k]!=up[v][k]) { res=Math.max(res,Math.max(upMax[u][k],upMax[v][k])); u=up[u][k]; v=up[v][k]; }
        return Math.max(res, Math.max(upMax[u][0], upMax[v][0]));
    }

    static int find(int[] d, int x) { return d[x]==x?x:(d[x]=find(d,d[x])); }
    static void union(int[] d, int x, int y) { d[find(d,x)]=find(d,y); }
}

