import java.util.*;

/*
 *  Solution outline:
 *
 *  For a query (s, t), we need a minimum-weight subset of edges such that
 *  every vertex is reachable from at least one of s or t in the chosen subgraph.
 *
 *  Equivalently, every connected component of the chosen subgraph must contain
 *  at least one of s or t. Since only two special vertices exist, the optimal
 *  chosen subgraph is a spanning forest with either:
 *    - one tree containing all vertices  -> any MST
 *    - two trees, one containing s and one containing t
 *
 *  So the answer is the minimum weight of a spanning forest with exactly two
 *  components separating s and t, OR one component if that is cheaper.
 *
 *  Let MST weight be W.
 *  In an MST tree T, for any pair (s, t), removing the maximum-weight edge on
 *  the path between s and t yields the minimum-weight 2-component spanning forest
 *  that separates s and t. Therefore:
 *
 *      answer(s, t) = W - maxEdgeOnPath_T(s, t)
 *
 *  because using one component costs W, and the two-component optimum is <= W;
 *  the formula already gives that minimum.
 *
 *  Thus:
 *    1. Build an MST using Kruskal.
 *    2. Preprocess binary lifting on the MST to answer maximum edge on path.
 *    3. For each query, print W - maxOnPath(s, t).
 */

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int u, v;
        long w;
        Edge(int u, int v, long w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
    }

    static class DSU {
        int[] p, sz;
        DSU(int n) {
            p = new int[n];
            sz = new int[n];
            for (int i = 0; i < n; i++) {
                p[i] = i;
                sz[i] = 1;
            }
        }
        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }
        boolean union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return false;
            if (sz[a] < sz[b]) {
                int t = a; a = b; b = t;
            }
            p[b] = a;
            sz[a] += sz[b];
            return true;
        }
    }

    static class AdjEdge {
        int to;
        long w;
        AdjEdge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        Edge[] edges = new Edge[M];
        for (int i = 0; i < M; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            long c = fs.nextLong();
            edges[i] = new Edge(a, b, c);
        }

        Arrays.sort(edges, Comparator.comparingLong(e -> e.w));

        List<AdjEdge>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        DSU dsu = new DSU(N);
        long mstWeight = 0;
        int used = 0;
        for (Edge e : edges) {
            if (dsu.union(e.u, e.v)) {
                mstWeight += e.w;
                used++;
                g[e.u].add(new AdjEdge(e.v, e.w));
                g[e.v].add(new AdjEdge(e.u, e.w));
                if (used == N - 1) break;
            }
        }

        int LOG = 1;
        while ((1 << LOG) <= N) LOG++;

        int[][] up = new int[LOG][N];
        long[][] mx = new long[LOG][N];
        int[] depth = new int[N];
        Arrays.fill(depth, -1);

        // iterative DFS/BFS from root 0 (graph connected)
        ArrayDeque<Integer> dq = new ArrayDeque<>();
        dq.add(0);
        depth[0] = 0;
        up[0][0] = 0;
        mx[0][0] = 0;

        while (!dq.isEmpty()) {
            int v = dq.poll();
            for (AdjEdge e : g[v]) {
                if (depth[e.to] != -1) continue;
                depth[e.to] = depth[v] + 1;
                up[0][e.to] = v;
                mx[0][e.to] = e.w;
                dq.add(e.to);
            }
        }

        for (int k = 1; k < LOG; k++) {
            for (int v = 0; v < N; v++) {
                int mid = up[k - 1][v];
                up[k][v] = up[k - 1][mid];
                mx[k][v] = Math.max(mx[k - 1][v], mx[k - 1][mid]);
            }
        }

        int Q = fs.nextInt();
        StringBuilder sb = new StringBuilder();

        for (int qi = 0; qi < Q; qi++) {
            int s = fs.nextInt() - 1;
            int t = fs.nextInt() - 1;

            long maxOnPath = getMaxOnPath(s, t, up, mx, depth, LOG);
            sb.append(mstWeight - maxOnPath).append('\n');
        }

        System.out.print(sb.toString());
    }

    static long getMaxOnPath(int a, int b, int[][] up, long[][] mx, int[] depth, int LOG) {
        long res = 0;
        if (depth[a] < depth[b]) {
            int t = a; a = b; b = t;
        }

        int diff = depth[a] - depth[b];
        for (int k = LOG - 1; k >= 0; k--) {
            if (((diff >> k) & 1) != 0) {
                res = Math.max(res, mx[k][a]);
                a = up[k][a];
            }
        }

        if (a == b) return res;

        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][a] != up[k][b]) {
                res = Math.max(res, mx[k][a]);
                res = Math.max(res, mx[k][b]);
                a = up[k][a];
                b = up[k][b];
            }
        }

        res = Math.max(res, mx[0][a]);
        res = Math.max(res, mx[0][b]);
        return res;
    }
}
